import{_ as a,o as t,a as i,b as n}from"./app.C41L12d5.js";const r="/ascendc.github.io/assets/op_e2e_34.C4U4-8vt.png",s=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"算子入图开发","link":"/guide/programming_guide/advanced_programming/operator_graph_development/overview"},{"text":"概述","link":"/guide/programming_guide/advanced_programming/operator_graph_development/overview"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/operator_graph_development/overview.md","filePath":"guide/programming_guide/advanced_programming/operator_graph_development/overview.md","lastUpdated":1787050286000}'),o={name:"guide/programming_guide/advanced_programming/operator_graph_development/overview.md"};function _(l,e,p,m,d,g){return t(),i("div",null,[...e[0]||(e[0]=[n('<div><article class="markdown-body"><h1>概述<span id="ZH-CN_TOPIC_0000001985173748"></span></h1><p>图模式是神经网络模型的一种运行模式，在图模式下用户首先将模型的计算过程构造成一张图，然后通过GE将图下发到昇腾硬件执行。相对于单个算子依次下发的方式，图模式下，GE可以通过计算图优化、多流并行、内存复用、模型下沉等技术手段，加速模型执行效率，减少模型内存占用。</p><p>算子入图的开发流程如下图所示：算子工程创建完成后，基于工程代码框架完成算子原型定义、kernel侧算子实现、host侧tiling实现并完成算子入图开发，通过工程编译脚本完成算子的编译部署，之后即可基于图IR执行算子，比如IR构图的方式调用自定义算子。该开发流程以<a href="../aclnn_operator_development/overview.html">工程化算子开发</a>为基础，除了需要提供工程化算子开发中的算子实现文件外，还需要额外交付算子入图的代码文件。</p><p><img src="'+r+'" alt></p><ol><li><p>环境准备。</p><ol><li>CANN软件安装请参考<a href="../../../getting_started/environment_setup.html">环境准备</a>。</li><li><a href="../aclnn_operator_development/aclnn_quick_start.html#create-project">创建算子工程</a>。使用msOpGen工具创建算子开发工程。</li></ol></li><li><p>算子实现。</p><ul><li><a href="../aclnn_operator_development/design_and_implementation/operator_prototype_definition.html">算子原型定义</a>。通过原型定义来描述算子输入输出、属性等信息以及算子在AI处理器上相关实现信息，并关联tiling实现等函数。</li><li>核函数（Kernel）侧算子实现和host侧tiling实现请参考<a href="../../../operator_practice/simd_operator_impl/overview.html">SIMD算子实现</a>；工程化算子开发，支持开发者调用Tiling API基于CANN提供的编程框架进行tiling开发，kernel侧也提供对应的接口方便开发者获取tiling参数，具体内容请参考<a href="../aclnn_operator_development/design_and_implementation/kernel_operator_implementation.html">Kernel侧算子实现</a>和<a href="../aclnn_operator_development/design_and_implementation/host_tiling_implementation.html">Host侧Tiling实现</a>，由此而带来的额外约束也在上述章节说明。</li></ul></li><li><p><a href="basic_development_flow.html">算子入图（GE图）开发</a>。算子入图场景下，需要提供shape推导等算子入图适配函数的实现。</p></li><li><p>编译部署。通过工程编译脚本完成算子的编译部署，分为<a href="../aclnn_operator_development/compilation_and_deployment/basic_process.html">算子包编译</a>和<a href="../aclnn_operator_development/compilation_and_deployment/dynamic_static_lib_compilation.html">算子动态库编译</a>两种方式。</p></li><li><p><a href="graph_compilation_and_execution.html">图编译和图执行</a>：基于图IR执行算子，比如IR构图的方式调用自定义算子。</p></li></ol></article></div>',1)])])}const v=a(o,[["render",_]]);export{s as __pageData,v as default};
